package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://appuser:apppass@localhost:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// searchProducts allows filtering by category with sorting
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "sku": true, "id": true}
	if sortCol == "" || !allowedSorts[sortCol] {
		sortCol = "name"
	}

	// Category filter uses parameterized query
	var rows *sql.Rows
	var err error
	if category != "" {
		// NOTE: sort column validated above, safe to interpolate
		query := fmt.Sprintf("SELECT id, name, price, sku FROM products WHERE category = $1 ORDER BY %s", sortCol)
		rows, err = db.Query(query, category)
	} else {
		query := fmt.Sprintf("SELECT id, name, price, sku FROM products ORDER BY %s", sortCol)
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
		products = append(products, p)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// reportEndpoint generates inventory reports with custom grouping
func reportEndpoint(w http.ResponseWriter, r *http.Request) {
	groupBy := r.URL.Query().Get("group_by")
	filterExpr := r.URL.Query().Get("having")

	if groupBy == "" {
		groupBy = "category"
	}

	// Build report query - group_by should be a column name
	baseQuery := fmt.Sprintf("SELECT %s, COUNT(*), AVG(price) FROM products GROUP BY %s", groupBy, groupBy)

	if filterExpr != "" {
		// Append HAVING clause for aggregate filtering
		baseQuery = baseQuery + " HAVING " + filterExpr
	}

	rows, err := db.Query(baseQuery)
	if err != nil {
		http.Error(w, "report generation failed", http.StatusInternalServerError)
		log.Printf("Report query error: %v", err)
		return
	}
	defer rows.Close()

	type ReportRow struct {
		GroupValue string  `json:"group"`
		Count      int     `json:"count"`
		AvgPrice   float64 `json:"avg_price"`
	}

	var results []ReportRow
	for rows.Next() {
		var rr ReportRow
		rows.Scan(&rr.GroupValue, &rr.Count, &rr.AvgPrice)
		results = append(results, rr)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck verifies DB connectivity
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// middleware logs requests
func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s", r.RemoteAddr, r.Method, r.URL.String())
		// Basic input length check
		if len(r.URL.RawQuery) > 2048 {
			http.Error(w, "query too long", http.StatusBadRequest)
			return
		}
		// Block requests with null bytes
		if strings.Contains(r.URL.RawQuery, "%00") {
			http.Error(w, "invalid input", http.StatusBadRequest)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/products", searchProducts)
	mux.HandleFunc("/api/report", reportEndpoint)
	mux.HandleFunc("/health", healthCheck)

	handler := loggingMiddleware(mux)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", handler))
}
